import{_ as i,C as t,o as e,c as d,a3 as o,b as n,w as s,a as c,E as l,a2 as u}from"./chunks/framework.rPoJfhSN.js";const g=JSON.parse('{"title":"Usuarios y permisos","description":"","frontmatter":{},"headers":[],"relativePath":"negocio/usuarios-permisos.md","filePath":"negocio/usuarios-permisos.md","lastUpdated":1786330671000}'),p={name:"negocio/usuarios-permisos.md"};function m(h,a,b,C,_,A){const r=t("Mermaid");return e(),d("div",null,[a[1]||(a[1]=o('<h1 id="usuarios-y-permisos" tabindex="-1">Usuarios y permisos <a class="header-anchor" href="#usuarios-y-permisos" aria-label="Permalink to &quot;Usuarios y permisos&quot;">​</a></h1><h2 id="actores" tabindex="-1">Actores <a class="header-anchor" href="#actores" aria-label="Permalink to &quot;Actores&quot;">​</a></h2><h3 id="visitante" tabindex="-1">Visitante <a class="header-anchor" href="#visitante" aria-label="Permalink to &quot;Visitante&quot;">​</a></h3><p>Explora catálogo, tiendas, páginas y promociones. Debe autenticarse para acciones personales como carrito persistente, wishlist o checkout.</p><h3 id="cliente" tabindex="-1">Cliente <a class="header-anchor" href="#cliente" aria-label="Permalink to &quot;Cliente&quot;">​</a></h3><p>Gestiona perfil y direcciones, compra, consulta pedidos, descarga productos digitales y publica reseñas según las reglas del sistema.</p><h3 id="vendedor" tabindex="-1">Vendedor <a class="header-anchor" href="#vendedor" aria-label="Permalink to &quot;Vendedor&quot;">​</a></h3><p>Es un usuario con rol <code>vendor</code> y una tienda asociada. Gestiona catálogo, pedidos, métodos de retiro y solicitudes. Ciertas rutas exigen correo verificado y KYC aprobado.</p><h3 id="administrador" tabindex="-1">Administrador <a class="header-anchor" href="#administrador" aria-label="Permalink to &quot;Administrador&quot;">​</a></h3><p>Usa el guard <code>admin</code>. Sus capacidades se asignan con roles y permisos de Spatie, separados de los roles de clientes y vendedores.</p><h2 id="capas-de-autorizacion" tabindex="-1">Capas de autorización <a class="header-anchor" href="#capas-de-autorizacion" aria-label="Permalink to &quot;Capas de autorización&quot;">​</a></h2>',11)),(e(),n(u,null,{default:s(()=>[l(r,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20R%5BPetici%C3%B3n%5D%20--%3E%20A%7B%C2%BFAutenticado%3F%7D%0A%20%20%20%20A%20--%20No%20--%3E%20X%5BLogin%20o%20401%5D%0A%20%20%20%20A%20--%20S%C3%AD%20--%3E%20E%7B%C2%BFCorreo%20verificado%3F%7D%0A%20%20%20%20E%20--%20No%20--%3E%20Y%5BVerificaci%C3%B3n%5D%0A%20%20%20%20E%20--%20S%C3%AD%20--%3E%20G%7B%C2%BFRol%20o%20guard%20correcto%3F%7D%0A%20%20%20%20G%20--%20No%20--%3E%20Z%5B403%5D%0A%20%20%20%20G%20--%20S%C3%AD%20--%3E%20K%7B%C2%BFKYC%20o%20permiso%20requerido%3F%7D%0A%20%20%20%20K%20--%20No%20--%3E%20OK%5BControlador%5D%0A%20%20%20%20K%20--%20S%C3%AD%2C%20no%20cumple%20--%3E%20Z%0A%20%20%20%20K%20--%20S%C3%AD%2C%20cumple%20--%3E%20OK%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="permisos-administrativos-sembrados" tabindex="-1">Permisos administrativos sembrados <a class="header-anchor" href="#permisos-administrativos-sembrados" aria-label="Permalink to &quot;Permisos administrativos sembrados&quot;">​</a></h2><p>El seeder define permisos para KYC, roles, usuarios de rol, categorías, etiquetas, marcas, productos, pedidos, ecommerce, secciones, suscriptores, retiros, páginas, anuncios, contactos, pagos y ajustes. El rol inicial de superadministración recibe el conjunto completo.</p><h2 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h2><ul><li>Comprueba propiedad del recurso además del rol: un vendedor sólo debe modificar su tienda y productos.</li><li>Usa políticas de Laravel para reglas por modelo.</li><li>Mantén el guard correcto al crear roles o permisos.</li><li>Audita cambios sensibles y accesos a documentos KYC.</li><li>No documentes ni publiques contraseñas creadas por seeders; rótalas al instalar.</li></ul><p>La entrega local constituye una excepción controlada: sus <a href="/docs/guia/cuentas-demo.html">cuentas demo</a> son públicas, están identificadas como no productivas y deben eliminarse o rotarse antes del despliegue.</p>',5))])}const q=i(p,[["render",m]]);export{g as __pageData,q as default};
